import{_ as l,o as r,c as e,a2 as i}from"./chunks/framework.D0_YsCyK.js";const f=JSON.parse('{"title":"流量转发与管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/forward.md","filePath":"guide/forward.md","lastUpdated":1792681374000}'),t={name:"guide/forward.md"};function o(n,a,s,d,h,g){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="流量转发与管理" tabindex="-1">流量转发与管理 <a class="header-anchor" href="#流量转发与管理" aria-label="Permalink to &quot;流量转发与管理&quot;">​</a></h1><p>面板保留了原有的转发面板功能：多用户、端口转发和隧道转发、配额与限速。</p><blockquote><p>术语对照：面板菜单与中转页里的 <strong>规则</strong> 标签就是本文档所说的转发 / 转发规则。</p></blockquote><h2 id="仪表盘-dashboard" tabindex="-1">仪表盘 (Dashboard) <a class="header-anchor" href="#仪表盘-dashboard" aria-label="Permalink to &quot;仪表盘 (Dashboard)&quot;">​</a></h2><p>登录系统后首先看到的是仪表盘，这里展示了系统的整体运行状态，包括：</p><ul><li>在线节点数量</li><li>用户总数</li><li>流量统计信息</li></ul><h2 id="节点管理-node" tabindex="-1">节点管理 (Node) <a class="header-anchor" href="#节点管理-node" aria-label="Permalink to &quot;节点管理 (Node)&quot;">​</a></h2><p>节点是实际承载流量转发的服务器。</p><ul><li><strong>添加节点</strong>: 点击“添加”，获取密钥用于节点端安装。</li><li><strong>管理</strong>: 可以查看节点在线状态、版本信息，以及对节点进行编辑或删除。</li></ul><h2 id="用户管理-user" tabindex="-1">用户管理 (User) <a class="header-anchor" href="#用户管理-user" aria-label="Permalink to &quot;用户管理 (User)&quot;">​</a></h2><p>管理员可以创建和管理普通用户。</p><ul><li><strong>创建用户</strong>: 设置用户名、密码、流量配额等。</li><li><strong>用户组</strong>: 可以将用户分配到不同的组 (Group)，便于统一管理权限或策略。</li></ul><h2 id="转发管理-forward" tabindex="-1">转发管理 (Forward) <a class="header-anchor" href="#转发管理-forward" aria-label="Permalink to &quot;转发管理 (Forward)&quot;">​</a></h2><p>这是核心功能区，用于设置端口转发规则。</p><ul><li><strong>端口转发</strong>: 将节点服务器的某个端口流量转发到目标地址。 <ul><li><strong>协议</strong>: 支持 TCP / UDP。</li><li><strong>入口</strong>: 选择入口节点和监听端口。</li><li><strong>出口</strong>: 设置目标 IP 和端口。</li></ul></li><li><strong>隧道转发</strong>: 流量经隧道在节点之间穿透，包括“前置 → IX → 落地”多跳线路，见 <a href="./relay">对接中转</a>。</li></ul><h3 id="转发引擎-realm" tabindex="-1">转发引擎（realm） <a class="header-anchor" href="#转发引擎-realm" aria-label="Permalink to &quot;转发引擎（realm）&quot;">​</a></h3><p>端口转发隧道（类型为端口转发）可在创建/编辑时选择<strong>转发引擎</strong>：</p><ul><li><strong>面板转发（默认）</strong>：由节点 agent（gost）直接转发，功能最全，支持转发级限速与连接数限制。</li><li><strong>realm</strong>：由独立的 realm 程序在入口节点上转发，资源占用低。面板会像管理内核一样在入口节点自动安装、监督 realm（一台节点一个 realm 实例，配置为该节点上全部 realm 转发）。</li></ul><p>使用 realm 的限制：</p><ul><li>仅支持端口转发隧道；入口节点不能是远程节点，也不能是 nftables 转发模式；节点 agent 需为支持 realm 的版本。</li><li><strong>不支持转发级限速和连接数限制</strong>：转发上设了限速/连接数时，同步会给出警告并忽略这两项。</li><li>负载策略只支持轮询（round robin）与 IP 哈希（hash）。</li></ul><p>使用 nftables 转发模式的限制：</p><ul><li><strong>不支持限速和连接数限制</strong>：转发上设了限速/连接数时，同步会给出警告并忽略这两项。</li></ul><p><strong>计费口径（重要）</strong>：两种引擎、两种节点转发模式（agent / nftables）的计费口径一致，没有“某引擎不计费”：</p><ul><li>流量按方向如实统计：<strong>入</strong> = 客户端→远端，出 = 远端→客户端。转发的「已用流量」↑ 显示入、↓ 显示出。</li><li>配额扣减按隧道上的<strong>计费模式</strong>执行：单向 = 只扣入方向流量；双向 = 入 + 出。之后再乘隧道的流量倍率（trafficRatio）。切换引擎（gost ↔ realm）或转发模式不改变计费口径，同一笔流量在任何引擎下入账一致。</li><li>计数来源不同：面板转发（gost）由 agent 上报转发字节；realm 由节点上的 nftables 端口计数器采集；nftables 模式由面板托管的 nftables 规则计数。三者在面板侧走同一套方向与配额逻辑（含 realm 在内的引擎切换只换数据面，不换口径）。</li><li>历史口径提示：1.3.1 起单向计费的方向由「按出」改为「按入」（与本节定义对齐）；该变更只对生效之后的流量起作用，<strong>历史已扣减的配额不回溯调整</strong>。</li><li>切换引擎时面板先释放旧引擎的监听再拉起新引擎，不会双占端口；切换前后的流量各自按发生时的计数来源入账，不会重复计。</li></ul><h3 id="端口占用与复用口径" tabindex="-1">端口占用与复用口径 <a class="header-anchor" href="#端口占用与复用口径" aria-label="Permalink to &quot;端口占用与复用口径&quot;">​</a></h3><ul><li>端口冲突只看<strong>同一节点上的同一端口</strong>：同一端口可以同时用在不同节点上，互不影响。</li><li>同一节点上，转发、隧道链路与入站共用同一端口空间，分配时统一做占用校验。</li><li>自定义入口端口（inPort）必须是 1–65535，且落在该节点的端口范围内，否则会被拒绝。</li><li>节点的「可用端口」范围只约束转发/中转/隧道入口端口（自动分配也从中取口）；入站的监听端口不受此范围约束，只做同节点占用冲突校验。</li><li>多入口转发不能自定义监听 IP（inIp）；编辑转发时不改监听 IP 会保留原 IP，切换隧道时才重置。</li></ul><h3 id="删除与端口回收" tabindex="-1">删除与端口回收 <a class="header-anchor" href="#删除与端口回收" aria-label="Permalink to &quot;删除与端口回收&quot;">​</a></h3><ul><li>gost 模式的转发删除后，节点上的监听服务随即移除，端口释放。</li><li>nftables 模式的转发删除走“先标记待删除（pending-delete）→ 后台对账确认节点侧规则已移除 → 删除记录”：节点离线时删除会进入 pending-delete，由后台任务按 1m / 5m / 30m / 2h 退避自动重试，上限 24h 后转人工处理；等待期间该端口仍视为占用，不会分配给新转发。管理员可通过节点页的 Pending Delete 管理接口查看待清理项，见 <a href="./nodes">节点管理</a>。</li></ul><h2 id="限制与策略-limit" tabindex="-1">限制与策略 (Limit) <a class="header-anchor" href="#限制与策略-limit" aria-label="Permalink to &quot;限制与策略 (Limit)&quot;">​</a></h2><ul><li><strong>限速</strong>: 可以对指定用户或指定隧道进行带宽限制，防止资源滥用。</li><li><strong>计费模式</strong>: 支持配置流量计算方式（单向或双向），适合运营场景。转发流量按入、出两个方向分别统计，配额扣减按计费口径累计。</li></ul><h2 id="系统配置-config" tabindex="-1">系统配置 (Config) <a class="header-anchor" href="#系统配置-config" aria-label="Permalink to &quot;系统配置 (Config)&quot;">​</a></h2><p>在此页面进行系统的全局设置。</p><h2 id="个人设置-profile" tabindex="-1">个人设置 (Profile) <a class="header-anchor" href="#个人设置-profile" aria-label="Permalink to &quot;个人设置 (Profile)&quot;">​</a></h2><ul><li><strong>修改密码</strong>: 为了安全，建议定期修改管理员密码。</li></ul>',34)])])}const m=l(t,[["render",o]]);export{f as __pageData,m as default};
